/* Guided offline onboarding. Numerical match limits remain design proposals. */
(function(root){
'use strict';
const M=typeof module!=='undefined'?require('./model.js'):root.EssenceDemo;
const guides=[
 {id:'warden',name:'The Warden',body:'hero',x:144,y:400,dir:2,gait:0,title:'Find your footing',lines:['Welcome to the Veil. Walk along this hall and meet our three guides before you enter the arena.','Move with WASD or arrow keys. On a phone, drag the thumbstick or hold an arrow. Movement follows four directions.']},
 {id:'arcanist',name:'The Arcanist',body:'mage',x:272,y:400,dir:2,gait:0,title:'Aim. Cast. Keep moving.',lines:['Choose Apocalipsis, press C or Prepare, then click or tap a rival. Prepare again for each cast. Space or Strike attacks directly in front of you.','Keep moving away from incoming spell markers. Hold the life or mana potion button to repeat it. N or Meditate recovers mana while you stand still.']},
 {id:'keeper',name:'The Keeper',body:'rogue',x:400,y:400,dir:2,gait:0,title:'Carry risk. Bank safety.',lines:['Defeated rivals drop essence. Stand on a crystal and press Q or Pick up. Carried essence drops when you fall; rivals can take it.','Fight a few rivals in the arena. A bank will appear nearby. Stay beside it until your carried essence has transferred. Secured essence stays safe.']}
];
function createTutorial(){const s=M.create();s.phase='hallway';s.player.x=80;s.player.y=464;s.tutorial={stage:'hallway',seen:[],dialog:null,page:0,arenaTime:0,bankRevealed:false,finalRead:false,hallTime:0};M.tell(s,'Walk right and meet the Warden. E or Talk opens a conversation.');return s;}
function nearGuide(s){if(s.phase!=='hallway')return null;return guides.filter(g=>Math.hypot(g.x-s.player.x,g.y-s.player.y)<100).sort((a,b)=>Math.hypot(a.x-s.player.x,a.y-s.player.y)-Math.hypot(b.x-s.player.x,b.y-s.player.y))[0]||null;}
function talk(s,id){if(!s.tutorial)return false;const g=id==='final'?{id:'final',name:'The Keeper',title:'Tutorial finished',lines:['You fought, collected essence and secured it. That is the core loop: keep fighting for more, or risk the journey to a bank.','Proposed full-match rules: eligible kills create new essence up to a round generation budget. Picking up or stealing existing essence never creates more.','A deposited-essence target would end the match, with a time limit as a fallback. The generation cap, deposit target, scoring and exact values are still TBD.','This is an offline tutorial. Your practice deposits do not affect a live account. Replay the hall or return to Nix when you are ready.']}:guides.find(g=>g.id===id);if(!g)return false;s.tutorial.dialog=g;s.tutorial.page=0;s.armed=false;s.player.step=null;M.clearPotionKeys(s);return true;}
function next(s){const t=s.tutorial;if(!t?.dialog)return false;if(++t.page<t.dialog.lines.length)return true;const id=t.dialog.id;if(id==='final')t.finalRead=true;else if(!t.seen.includes(id))t.seen.push(id);t.dialog=null;t.page=0;return false;}
function enterArena(s){if(s.tutorial.seen.length!==guides.length)return false;s.phase='arena';s.tutorial.stage='fight';s.player.x=304;s.player.y=432;s.player.step=null;s.flash=.7;M.tell(s,'Defeat two rivals and collect their essence. A nearby bank will reveal itself.');return true;}
const originalUpdate=M.update,originalPickup=M.pickup,originalCast=M.cast,originalMelee=M.melee,originalInteract=M.interact;
M.pickup=function(s,radius){const n=originalPickup(s,radius);if(s.tutorial&&!s.tutorial.bankRevealed){s.bankUnlocked=false;if(n)M.tell(s,'Essence collected. Defeat two rivals to reveal the bank nearby.');}return n;};
M.cast=(s,target)=>s.phase==='hallway'||s.tutorial?.stage==='complete'?(s.armed=false,false):originalCast(s,target);
M.melee=s=>s.phase==='hallway'||s.tutorial?.stage==='complete'?false:originalMelee(s);
M.interact=function(s){if(s.phase==='hallway'){const g=nearGuide(s);if(g){talk(s,g.id);return 'talk';}if(s.player.x>=432&&enterArena(s))return 'enter';return false;}if(M.pickup(s,22))return 'pickup';if(M.nearBank(s))return 'bank';if(M.nearGate(s))return 'exit';return false;};
function revealBank(s){const t=s.tutorial;const candidates=[{x:432,y:624},{x:784,y:464},{x:944,y:720},{x:368,y:304}];const valid=candidates.filter(b=>Math.hypot(b.x-s.player.x,b.y-s.player.y)>65&&!s.enemies.some(e=>e.hp>0&&Math.abs(e.x-b.x)<70&&Math.abs(e.y-b.y)<65)&&!s.drops.some(d=>Math.abs(d.x-b.x)<60&&Math.abs(d.y-b.y)<40));valid.sort((a,b)=>Math.hypot(a.x-s.player.x,a.y-s.player.y)-Math.hypot(b.x-s.player.x,b.y-s.player.y));if(!valid.length)return;s.bankPosition={...(valid[0])};s.bankUnlocked=true;t.bankRevealed=true;t.stage='deposit';s.flash=.5;M.tell(s,'The bank has appeared nearby. Follow BANK, collect your crystals, then stay close to deposit.');}
M.update=function(s,dt,input={x:0,y:0}){if(!s.tutorial)return originalUpdate(s,dt,input);const t=s.tutorial;dt=Math.max(0,Math.min(dt,.05));if(t.dialog)return;
 if(s.phase==='hallway'){s.time+=dt;t.hallTime+=dt;s.flash=Math.max(0,s.flash-dt);const p=s.player,v=M.cardinal(input.x||0,input.y||0),beforeX=p.x,beforeY=p.y;p.x=Math.max(48,Math.min(t.seen.length===3?496:432,p.x+v.x*160*dt));p.y=Math.max(448,Math.min(496,p.y+v.y*160*dt));p.moving=p.x!==beforeX||p.y!==beforeY;if(p.moving){p.dir=v.x?(v.x>0?1:3):(v.y>0?2:0);p.gait+=Math.hypot(p.x-beforeX,p.y-beforeY);}const g=nearGuide(s);if(g&&!t.seen.includes(g.id)&&t.hallTime>=.65)talk(s,g.id);if(p.x>=464){if(!enterArena(s))M.tell(s,'Meet all three guides before entering the arena.');}return;}
 if(t.stage==='complete'){s.time+=dt;s.streamParticles=s.streamParticles.filter(p=>(p.age+=dt)<.55);return;}
 t.arenaTime+=dt;const previousSecured=s.secured;originalUpdate(s,dt,input);if(!t.bankRevealed&&(s.kills>=2||t.arenaTime>=90))revealBank(s);
 if(t.bankRevealed&&s.secured>previousSecured&&s.carried===0){t.stage='complete';s.won=true;s.armed=false;s.fx=[];for(const e of s.enemies)e.wind=0;talk(s,'final');M.tell(s,'Tutorial finished. Your essence is secure.');}
};
Object.assign(M,{guides,createTutorial,nearGuide,talk,nextGuide:next,enterArena,revealBank});
if(typeof module!=='undefined')module.exports=M;
})(typeof window!=='undefined'?window:globalThis);
